import{c as e,Q as r,j as o,m as n}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"软件工程-系统运行与维护","description":"","frontmatter":{"title":"软件工程-系统运行与维护"},"headers":[],"relativePath":"综合知识/软件工程/系统运行与维护.md","filePath":"综合知识/软件工程/系统运行与维护.md","lastUpdated":null}'),a={name:"综合知识/软件工程/系统运行与维护.md"};function d(s,t,l,g,i,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="系统转换" tabindex="-1">系统转换 <a class="header-anchor" href="#系统转换" aria-label="Permalink to &quot;系统转换&quot;">​</a></h3><h4 id="遗留系统处置策略" tabindex="-1">遗留系统处置策略 <a class="header-anchor" href="#遗留系统处置策略" aria-label="Permalink to &quot;遗留系统处置策略&quot;">​</a></h4><p>遗留系统是指任何基本上不能进行修改和演化以满足新的变化了的业务需求的信息系统</p><blockquote><p>遗留系统：不能进行修改和演化以满足新业务需求的信息系统。特点：性能落后、技术过时、无文档、难维护。</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517223711.png" alt="image.png"></p><table tabindex="0"><thead><tr><th>策略</th><th>条件</th></tr></thead><tbody><tr><td><strong>淘汰</strong></td><td>低业务价值 + 低系统质量</td></tr><tr><td><strong>继承</strong></td><td>高业务价值 + 低系统质量</td></tr><tr><td><strong>改造</strong></td><td>高业务价值 + 高系统质量</td></tr><tr><td><strong>集成</strong></td><td>低业务价值 + 高系统质量</td></tr></tbody></table><hr><h4 id="系统转换方式" tabindex="-1">系统转换方式 <a class="header-anchor" href="#系统转换方式" aria-label="Permalink to &quot;系统转换方式&quot;">​</a></h4><blockquote><p>🎯 一句话结论：系统转换有4种方式，<strong>并行转换</strong>最安全（新旧系统同时运行一段时间）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th>说明</th><th style="text-align:center;">风险</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>直接转换</strong></td><td>直接切换到新系统</td><td style="text-align:center;">高</td></tr><tr><td style="text-align:left;"><strong>并行转换</strong></td><td>新旧系统同时运行一段时间，验证后再切换</td><td style="text-align:center;">低</td></tr><tr><td style="text-align:left;"><strong>分段转换</strong></td><td>按模块/区域逐步切换</td><td style="text-align:center;">中</td></tr><tr><td style="text-align:left;"><strong>渐进式转换</strong></td><td>逐步演进替换</td><td style="text-align:center;">中</td></tr></tbody></table><p>数据转换与迁移：将数据从旧数据库迁移到新数据库中。要在新系统中尽可能的保存旧系统中合理的数据结构，才能降低迁移的难度。</p><p>也有三种方法：系统切换前通过工具迁移、系统切换前采用手工录入、系统切换后通过新系统生成。</p><h3 id="软件维护概述" tabindex="-1">软件维护概述 <a class="header-anchor" href="#软件维护概述" aria-label="Permalink to &quot;软件维护概述&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517224015.png" alt="image.png"></p><hr><blockquote><p>🎯 一句话结论：维护分4种 — <strong>改正性</strong>（修BUG）、<strong>适应性</strong>（适应新环境）、<strong>完善性</strong>（加功能）、<strong>预防性</strong>（用今天方法优化昨天系统为明天需求）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th>触发原因</th><th>考试关键词</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>改正性维护</strong></td><td>发现性能缺陷/Bug 需要诊断改正</td><td>&quot;发现性能缺陷进行诊断和改正&quot;</td></tr><tr><td style="text-align:left;"><strong>适应性维护</strong></td><td>外部环境变化（新OS、新硬件）</td><td>&quot;适应新操作系统&quot;</td></tr><tr><td style="text-align:left;"><strong>完善性维护</strong></td><td>用户提出新功能/性能要求</td><td>&quot;增加新功能&quot;</td></tr><tr><td style="text-align:left;"><strong>预防性维护</strong></td><td>主动预防未来可能的问题</td><td><strong>&quot;把今天的方法学用于昨天的系统以满足明天的需要&quot;</strong></td></tr></tbody></table><blockquote><p>⚠️ 易错辨析：「改正性」是修复已有错误（被动），「预防性」是主动预防未来问题。</p></blockquote><p><strong>影响软件维护的因素：</strong> 文档质量（是决定因素）、软件复杂度、人员变动等。 <strong>软件可维护性度量：</strong> 外部用 MTTR（平均修复时间），内部用软件复杂性间接度量。 <strong>软件维护阶段占整个生命周期 60% 以上的时间。</strong></p><hr><h3 id="净室软件工程" tabindex="-1">净室软件工程 <a class="header-anchor" href="#净室软件工程" aria-label="Permalink to &quot;净室软件工程&quot;">​</a></h3><blockquote><p>以数学和统计学为基础，强调<strong>从源头预防缺陷</strong>，而非先开发再测试修复。</p></blockquote><p><strong>核心理念：</strong> 预防胜于修复、统计质量控制、零缺陷开发。</p><p><strong>应用技术：</strong> 统计过程控制（增量开发中监控质量）、基于函数的规范与设计、正确性验证（编码前验证）、统计测试和软件认证。</p><p><strong>缺点：</strong> 理论化（需数学知识）、耗时（正确性验证困难）、不进行传统模块测试可能不现实。</p>',25)])])}const u=e(a,[["render",d]]);export{p as __pageData,u as default};
